CREATE TABLE IF NOT EXISTS project_review_claims(project_id TEXT PRIMARY KEY REFERENCES projects(id), review_id TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES clients(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS project_review_claim_guard BEFORE INSERT ON project_review_claims WHEN NOT EXISTS(SELECT 1 FROM projects p JOIN quotations q ON q.id=p.quotation_id JOIN service_requests r ON r.id=q.request_id JOIN customer_accounts a ON a.client_id=r.client_id JOIN reviews v ON v.id=NEW.review_id AND v.client_id=r.client_id WHERE p.id=NEW.project_id AND p.status='completed' AND r.client_id=NEW.client_id AND a.status='active' AND a.email_verified_at IS NOT NULL AND v.approved=0 AND v.rating BETWEEN 1 AND 5 AND length(trim(v.review)) BETWEEN 10 AND 2000) BEGIN SELECT RAISE(ABORT,'Review not eligible'); END;
